BEGIN; CREATE TABLE result(seq INTEGER,source INTEGER,t TEXT); WITH RECURSIVE q(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM q WHERE n<9999) INSERT INTO result SELECT q.n,1,t1.t FROM q JOIN t1 ON t1.rowid=q.n*3 WHERE q.n%3=0 UNION ALL SELECT q.n,2,t2.t FROM q JOIN t2 ON t2.rowid=q.n*3 WHERE q.n%3=1 UNION ALL SELECT q.n,3,t3.t FROM q JOIN t3 ON t3.rowid=q.n*3 WHERE q.n%3=2; COMMIT;